                code: { lang: "python", run: true, src: String.raw`import numpy as np
import pandas as pd

np.random.seed(42)                     # 난수 고정: 실행할 때마다 같은 데이터
years = np.arange(1907, 2023)          # 1907년 ~ 2022년
temps = 10.6 + 0.022 * (years - 1907) + np.random.normal(0, 0.5, len(years))
seoul = pd.DataFrame({'연도': years, '평균 기온': temps.round(1)})   # 연습용 데이터

print('행, 열 수:', seoul.shape)
seoul.head()` },
