                code: { lang: "python", run: true, src: String.raw`def find_outliers(data, col):
    idx = []
    for kind, group in data.groupby('종류'):
        q1 = group[col].quantile(0.25)
        q3 = group[col].quantile(0.75)
        iqr = q3 - q1
        out = group[(group[col] < q1 - 1.5 * iqr) | (group[col] > q3 + 1.5 * iqr)]
        idx += list(out.index)
    return idx

all_idx = set()
for col in ['꽃받침 길이', '꽃받침 너비', '꽃잎 길이', '꽃잎 너비']:
    found = find_outliers(df3, col)
    print(col, '이상치 인덱스:', found)
    all_idx.update(found)

df3 = df3.drop(index=sorted(all_idx), axis=0)      # 이상치 행 제거
print('제거한 행 수:', len(all_idx), ' 남은 크기:', df3.shape)
print(df3.describe().loc[['mean', 'max']].round(2))` },
